CREATE SET TABLE MDP01_META.META_ETL_COLUMN_MAPPING ,FALLBACK ,     NO BEFORE JOURNAL,     NO AFTER JOURNAL,     CHECKSUM = DEFAULT,     DEFAULT MERGEBLOCKRATIO,     MAP = TD_MAP1     (      mapping_id INTEGER NOT NULL,      etl_job_id INTEGER NOT NULL,      source_column_id INTEGER,      target_column_id INTEGER NOT NULL,      transformation_expr VARCHAR(2000) CHARACTER SET LATIN NOT CASESPECIFIC,      is_calculated CHAR(1) CHARACTER SET LATIN NOT CASESPECIFIC DEFAULT 'N',      is_business_key CHAR(1) CHARACTER SET LATIN NOT CASESPECIFIC DEFAULT 'N',      mapping_type VARCHAR(50) CHARACTER SET LATIN NOT CASESPECIFIC,      default_value VARCHAR(500) CHARACTER SET LATIN NOT CASESPECIFIC,      is_manually_maintained CHAR(1) CHARACTER SET LATIN NOT CASESPECIFIC DEFAULT 'Y',      ersterfassungsdatum TIMESTAMP(6) NOT NULL,      aenderungsdatum TIMESTAMP(6) NOT NULL)PRIMARY INDEX ( mapping_id )INDEX ( etl_job_id );